package com.yjiyun.chatflows.runtime.api;
import com.sun.net.httpserver.*; import com.yjiyun.chatflows.runtime.blueprint.*; import com.yjiyun.chatflows.runtime.security.AuthService; import java.io.IOException; import java.util.Map;
public final class PublishController implements HttpHandler { private final BlueprintAdmin admin; private final AuthService auth; public PublishController(BlueprintAdmin a,AuthService auth){admin=a;this.auth=auth;} public void handle(HttpExchange x)throws IOException{if(!"POST".equals(x.getRequestMethod())){HttpSupport.json(x,405,Map.of("error","POST required"));return;}try{auth.requireAdmin(HttpSupport.bearer(x),x.getRequestHeaders().getFirst("X-Role"));Map<String,String> q=HttpSupport.query(x);String actor=x.getRequestHeaders().getFirst("X-Actor");if(actor==null||actor.isBlank())throw new IllegalArgumentException("X-Actor required");BlueprintAdmin.Result bp;if(x.getRequestURI().getPath().endsWith("/rollback")){bp=admin.rollback(req(q,"clientCode"),req(q,"runtimeAgentId"),Integer.parseInt(req(q,"version")),actor);}else{bp=admin.publish(req(q,"blueprintId"),req(q,"clientCode"),actor);}HttpSupport.json(x,200,Map.of("blueprintId",bp.blueprintId(),"version",bp.version(),"status",bp.status()));}catch(Exception e){HttpSupport.error(x,e);}} private static String req(Map<String,String> q,String k){String v=q.get(k);if(v==null||v.isBlank())throw new IllegalArgumentException(k+" required");return v;} }
